from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Ref:
    col: int
    row: int
    abs_col: bool = False
    abs_row: bool = False

__all__ = ["parse_ref", "parse_range", "to_a1"]

_REF_RE = re.compile(r"(\$?)([A-Za-z]{1,2})(\$?)([1-9][0-9]{0,3})")
_MAX_COL = 701  # ZZ
_MAX_ROW = 9998  # row 9999, 0-based


def _col_index(letters: str) -> int:
    n = 0
    for ch in letters.upper():
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n - 1


def _col_letters(col: int) -> str:
    out = []
    n = col + 1
    while n > 0:
        n, rem = divmod(n - 1, 26)
        out.append(chr(ord("A") + rem))
    return "".join(reversed(out))


def parse_ref(s: str) -> Ref:
    m = _REF_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid cell reference: {s!r}")
    abs_col = m.group(1) == "$"
    abs_row = m.group(3) == "$"
    return Ref(_col_index(m.group(2)), int(m.group(4)) - 1, abs_col, abs_row)


def parse_range(s: str) -> tuple[Ref, Ref]:
    parts = s.split(":")
    if len(parts) != 2:
        raise ValueError(f"invalid range: {s!r}")
    first = parse_ref(parts[0])
    second = parse_ref(parts[1])
    # Each axis: min/max corner supplies the flag; tie goes to the first corner.
    if second.col < first.col:
        min_col_src, max_col_src = second, first
    else:
        min_col_src, max_col_src = first, second
    if second.row < first.row:
        min_row_src, max_row_src = second, first
    else:
        min_row_src, max_row_src = first, second
    top_left = Ref(min_col_src.col, min_row_src.row, min_col_src.abs_col, min_row_src.abs_row)
    bottom_right = Ref(max_col_src.col, max_row_src.row, max_col_src.abs_col, max_row_src.abs_row)
    return top_left, bottom_right


def to_a1(ref: Ref) -> str:
    if not (0 <= ref.col <= _MAX_COL and 0 <= ref.row <= _MAX_ROW):
        raise ValueError(f"reference out of range: col={ref.col} row={ref.row}")
    prefix_col = "$" if ref.abs_col else ""
    prefix_row = "$" if ref.abs_row else ""
    return f"{prefix_col}{_col_letters(ref.col)}{prefix_row}{ref.row + 1}"

